import{_ as e,a as t,c as r,ac as o}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"macOS 桌面与终端使用笔记","description":"集中保留 Finder、全屏、应用默认打开方式和终端接入小提示。","frontmatter":{"title":"macOS 桌面与终端使用笔记","description":"集中保留 Finder、全屏、应用默认打开方式和终端接入小提示。","showdocs":{"topics":[{"id":"macos","title":"macOS","link":"/topics/macos/"}],"kind":"命令与观察","scope":"general","audience":"general","group":"容器与运维","summary":"集中保留 Finder、全屏、应用默认打开方式和终端接入小提示。","status":"active","related":[{"title":"macOS：部署 LaunchAgent 与本地维护任务","link":"/systems/operating-systems/macos/plus/practice/application","kind":"完整实践","scope":"general","audience":"general"},{"title":"macOS：配置变更、排障与恢复","link":"/systems/operating-systems/macos/operations","kind":"知识专题","scope":"general","audience":"general"},{"title":"macOS：系统对象、身份与服务机制","link":"/systems/operating-systems/macos/system-model","kind":"知识专题","scope":"general","audience":"general"},{"title":"macOS 文件、磁盘与目录命令","link":"/systems/operating-systems/macos/file-commands","kind":"命令与观察","scope":"general","audience":"general"},{"title":"macOS 文件、磁盘与目录命令 · 检查容量、卷与文件系统至macOS 查看目录占用","link":"/systems/operating-systems/macos/file-commands-part-02","kind":"命令与观察","scope":"general","audience":"general"}],"prev":{"text":"macOS 文件、磁盘与目录命令 · 检查容量、卷与文件系统至macOS 查看目录占用","link":"/systems/operating-systems/macos/file-commands-part-02"},"next":{"text":"macOS：进程、服务与资源","link":"/systems/operating-systems/macos/plus/ecosystem/macos-process-general-general"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"macOS 文件、磁盘与目录命令 · 检查容量、卷与文件系统至macOS 查看目录占用","link":"/systems/operating-systems/macos/file-commands-part-02"},"next":{"text":"macOS：进程、服务与资源","link":"/systems/operating-systems/macos/plus/ecosystem/macos-process-general-general"}},"headers":[],"relativePath":"systems/operating-systems/macos/desktop-workflow.md","filePath":"systems/operating-systems/macos/desktop-workflow.md"}'),s={name:"systems/operating-systems/macos/desktop-workflow.md"};function l(n,a,p,i,c,m){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="macos-桌面与终端使用笔记" tabindex="-1">macOS 桌面与终端使用笔记 <a class="header-anchor" href="#macos-桌面与终端使用笔记" aria-label="Permalink to &quot;macOS 桌面与终端使用笔记&quot;">​</a></h1><h2 id="part-1" tabindex="-1">macOS 文件、进程与终端操作 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;macOS 文件、进程与终端操作 {#part-1}&quot;">​</a></h2><p>本节是旧环境笔记，系统版本与多数应用版本未记录；以下只解释当时场景，未执行。现在排查先读<a href="/systems/operating-systems/macos/system-model">用户身份与后台环境</a>。</p><h3 id="part-1-实现系统文件不能修改" tabindex="-1">实现系统文件不能修改 <a class="header-anchor" href="#part-1-实现系统文件不能修改" aria-label="Permalink to &quot;实现系统文件不能修改 {#part-1-实现系统文件不能修改}&quot;">​</a></h3><p>原场景是用 root 创建了自己的项目，普通用户无法编辑。先确认确切项目路径及所有权，再只修正确需移交的对象；“系统文件不能修改”也可能涉及 SIP/TCC 或只读卷，不能统一用 chown 解决。</p><p>原递归 chown 命令不作为通用步骤：从错误工作目录执行会更改无关内容，项目中也可能有应由其他账户拥有的文件。文件访问层次见<a href="/systems/operating-systems/macos/system-model#part-2-privacy">系统权限边界</a>。</p><h3 id="part-1-每次需要手动配置文件" tabindex="-1">每次需要手动配置文件 <a class="header-anchor" href="#part-1-每次需要手动配置文件" aria-label="Permalink to &quot;每次需要手动配置文件 {#part-1-每次需要手动配置文件}&quot;">​</a></h3><p>自己在 ~/.bash_profile 中配置环境变量, 可是每次重启终端后配置的不生效.需要重新执行 : $source ~/.bash_profile</p><p>发现zsh加载的是 ~/.zshrc文件，而 ‘.zshrc’ 文件中并没有定义任务环境变量。</p><p>解决办法</p><p>在~/.zshrc文件最后，增加一行： source ~/.bash_profile</p><h3 id="part-1-查看端口且终止此端口" tabindex="-1">查看端口且终止此端口 <a class="header-anchor" href="#part-1-查看端口且终止此端口" aria-label="Permalink to &quot;查看端口且终止此端口 {#part-1-查看端口且终止此端口}&quot;">​</a></h3><blockquote><p>查看8080端口占用情况</p></blockquote><p>lsof -i :8080</p><blockquote><p>lsof 返回的是监听进程线索，不能“终止端口”。核对当前 PID、程序路径和所属服务后，优先通过原管理器正常停止；仅在必要时对已确认 PID 发送 SIGTERM。旧 kill -9 跳过清理，不作默认修复。</p></blockquote><h3 id="part-1-查找文件" tabindex="-1">查找文件 <a class="header-anchor" href="#part-1-查找文件" aria-label="Permalink to &quot;查找文件 {#part-1-查找文件}&quot;">​</a></h3><p>mdfind -name &quot;daemon.json&quot;</p><h3 id="part-1-访达转向-系统文件" tabindex="-1">访达转向 系统文件 <a class="header-anchor" href="#part-1-访达转向-系统文件" aria-label="Permalink to &quot;访达转向 系统文件 {#part-1-访达转向-系统文件}&quot;">​</a></h3><blockquote><p>Command + Shift + G</p></blockquote><h3 id="part-1-多屏显示-主次屏幕" tabindex="-1">多屏显示 主次屏幕 <a class="header-anchor" href="#part-1-多屏显示-主次屏幕" aria-label="Permalink to &quot;多屏显示 主次屏幕 {#part-1-多屏显示-主次屏幕}&quot;">​</a></h3><blockquote><p><a href="https://blog.csdn.net/qq_37465368/article/details/81104824" target="_blank" rel="noopener noreferrer">参考链接</a><br> 系统偏好设置 --&gt; 显示器 --&gt; 排列 --&gt; 拖动</p></blockquote><h3 id="part-1-修改文件始终打开方式" tabindex="-1">修改文件始终打开方式 <a class="header-anchor" href="#part-1-修改文件始终打开方式" aria-label="Permalink to &quot;修改文件始终打开方式 {#part-1-修改文件始终打开方式}&quot;">​</a></h3><blockquote><p><a href="https://sspai.com/post/28394" target="_blank" rel="noopener noreferrer">参考链接</a></p></blockquote><ul><li>方式一：</li></ul><blockquote><p>右击文件--&gt; 按下Option键--&gt; 选择始终此方式打开</p></blockquote><ul><li>方式二：</li></ul><blockquote><p>右击文件--&gt; 选择简介--&gt; 修改打开方式</p></blockquote><h3 id="part-1-安装-brew-和-换源地址" tabindex="-1">安装 brew 和 换源地址 <a class="header-anchor" href="#part-1-安装-brew-和-换源地址" aria-label="Permalink to &quot;安装 brew 和 换源地址 {#part-1-安装-brew-和-换源地址}&quot;">​</a></h3><p>原记录使用第三方镜像脚本安装 Homebrew；远程脚本下载后立即执行不是这里的完整安装方案。安装渠道与平台前置按 <a href="https://brew.sh/index_zh-cn" target="_blank" rel="noopener noreferrer">Homebrew 官方说明</a>核对；<a href="https://mirrors.tuna.tsinghua.edu.cn/help/homebrew/" target="_blank" rel="noopener noreferrer">清华镜像说明</a>只解释该镜像的设置，不代表已确认当前可用。</p><p><span id="part-1-macos-utils"></span></p><h2 id="part-2" tabindex="-1">macOS 全屏快捷键 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;macOS 全屏快捷键 {#part-2}&quot;">​</a></h2><p>在支持全屏的应用中，按 <strong>Control + Command + F</strong> 切换全屏状态。</p><p><span id="part-2-mac-os-快捷键"></span><span id="part-2-窗口最大化"></span></p><h2 id="part-3" tabindex="-1">go2shell <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;go2shell {#part-3}&quot;">​</a></h2><h3 id="part-3-访达找不到go2shell" tabindex="-1">访达找不到go2shell <a class="header-anchor" href="#part-3-访达找不到go2shell" aria-label="Permalink to &quot;访达找不到go2shell {#part-3-访达找不到go2shell}&quot;">​</a></h3><blockquote><p><a href="https://my.oschina.net/1715828751/blog/4785100" target="_blank" rel="noopener noreferrer">参考链接</a></p></blockquote><h4 id="part-3-方法" tabindex="-1">方法 <a class="header-anchor" href="#part-3-方法" aria-label="Permalink to &quot;方法 {#part-3-方法}&quot;">​</a></h4><ul><li>找到Go2ShellHelper 文件该快捷方式的路径为/Applications/Go2Shell.app/Contents/MacOS</li><li>按下快捷键command + shift + g 输入上面的路基即可</li><li>讲Go2ShellHelper 拖动到 toolbar上去即可 有人尝试过拖不上去，可以尝试 按下 command 键试一下</li></ul>',38)])])}const u=e(s,[["render",l]]);export{d as __pageData,u as default};
